import { useTheme } from '@emotion/react';
import * as React from 'react';

import CancelIcon from '@mui/icons-material/Cancel';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import { Box, SvgIcon, Typography } from '@mui/material';

import MainButton from 'components/ui/MainButton';
import { pxToRem } from 'util/util';

const GameButton = (props) => {
    const {
        // text,
        // colorEffect = '000',
        // // stroke = false,
        // distance = pxToRem(3),
        // patternZoom = 2,
        onClick,
        phase,
        choice,
        rightAnswer,
        chosenAnswer,
        isFlag,
        answerAdditionnalText,
    } = props;
    const theme = useTheme();

    let color = 'primary';
    let icon = undefined;
    if (phase === 2) {
        if (
            (choice?.value ?? choice) === (rightAnswer?.value ?? rightAnswer) &&
            (chosenAnswer?.value ?? chosenAnswer) === (choice?.value ?? choice)
        ) {
            color = 'success';
            icon = <CheckCircleIcon />;
        } else if ((choice?.value ?? choice) === (rightAnswer?.value ?? rightAnswer)) {
            color = 'secondary';
        } else if ((choice?.value ?? choice) === (chosenAnswer?.value ?? chosenAnswer)) {
            color = 'error';
            icon = <CancelIcon />;
        }
    }

    return (
        <MainButton
            buttonP={{
                color: color,
                onClick: onClick,
                variant: isFlag ? 'outlined' : 'contained',
                // variant: 'outlined',
                // variant: isFlag || (phase === 1 && choice !== rightAnswer && chosenAnswer !== choice) ? 'outlined' : 'contained',
                sx: {
                    position: 'relative',
                    ...(color === 'secondary' || color === 'success'
                        ? {
                              outlineOffset: pxToRem(3),
                              outline: `2px solid ${color === 'success' ? theme.palette[color].main : theme.palette.background.rightAnswer}`,
                          }
                        : {}),
                    // ...(phase === 0 ? {
                    // backgroundColor: "#fff",
                    // '&:hover': {
                    // 	backgroundColor: "rgba(255,255,255,0.5)",
                    // },
                    // } : {}),
                    textAlign: 'center',
                    // width: isFlag ? `calc(50% - ${pxToRem(8)})` : '100%',
                    width: '100%',
                    ...(isFlag ? { minHeight: '126px', backgroundColor: theme.palette.neutral[50] } : {}),
                    padding: pxToRem(10),
                    cursor: phase === 2 ? 'initial' : 'pointer',
                },
                ...(!isFlag && icon
                    ? {
                          endIcon: <SvgIcon
									sx={{
                                        width: pxToRem(24),
                                        height: pxToRem(24),
									}}>{icon}</SvgIcon>,
                      }
                    : {}),
            }}
            typoP={{
                fontSize: pxToRem(20),
                fontWeight: '700',
                lineHeight: pxToRem(26),
            }}
            isFlag={isFlag}
        >
            {props.children}
            {choice === rightAnswer && phase === 2 && answerAdditionnalText ? (
                <>
                    <br />
                    <Typography component="sub" lineHeight="1.5" display="block">
                        {answerAdditionnalText}
                    </Typography>
                </>
            ) : null}
            {isFlag && icon && (
                <Box
                    sx={{
                        position: 'absolute',
						backgroundColor: `${theme.palette[color].main}`,
                        right: -1,
                        bottom: -1,
						borderBottomRightRadius: pxToRem(13),
						borderTopLeftRadius: pxToRem(13),
						width: pxToRem(36),
						height: pxToRem(36),
						display: 'flex',
						justifyContent: 'center',
						alignItems: 'center',
						filter: 'drop-shadow(-1px -1px 2px rgba(0, 0, 0, 0.2))',
						svg: {
							color: theme.palette.primary.contrastText,
						},
                    }}
                >
                    {icon}
                </Box>
            )}
        </MainButton>
    );
};

export default GameButton;
